const AdmZip = require('adm-zip');
const MAX_FILES = 10000;
const MAX_SIZE = 1000000000;
const THRESHOLD_RATIO = 10;
let fileCount = 0;
let totalSize = 0;
const zip = new AdmZip('./foo.zip');
for (const zipEntry of zip.getEntries()) {
  fileCount++;
  if (fileCount > MAX_FILES) throw new Error('Reached max. number of files');
  const entrySize = zipEntry.getData().length;
  totalSize += entrySize;
  if (totalSize > MAX_SIZE) throw new Error('Reached max. size');
  const compressionRatio = entrySize / zipEntry.header.compressedSize;
  if (compressionRatio > THRESHOLD_RATIO) throw new Error('Reached max. compression ratio');
  if (!zipEntry.isDirectory) zip.extractEntryTo(zipEntry.entryName, '.');
}
module.exports = { zip };

